package org.pocketsurf.browser

import android.content.Intent
import android.graphics.Color
import android.graphics.Rect
import android.graphics.drawable.ColorDrawable
import android.net.Uri
import android.os.Looper
import android.view.*
import android.view.inputmethod.EditorInfo
import android.webkit.WebView
import android.widget.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config
import java.time.Duration

/** Native host contracts only: no real Chromium page/IME/physical-device claim. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi",shadows=[RecordingWebViewShadow::class])
class Release10RegressionTest {
 @Before fun fixture(){RuntimeEnvironment.getApplication().getSharedPreferences("browser",0).edit().putBoolean(SetupActivity.COMPLETE,true).commit();RecordingWebViewShadow.clearEvidence()}
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun views(a:BrowserActivity)=all(a.window.decorView)
 private fun desc(a:BrowserActivity,s:String)=views(a).first{it.contentDescription?.toString()==s}
 private fun label(a:BrowserActivity,s:String)=views(a).filterIsInstance<TextView>().firstOrNull{it.text.toString()==s}
 private fun settle(a:BrowserActivity){repeat(3){views(a).forEach{it.forceLayout()};a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)};TestFrameClock.advance(Duration.ofMillis(16))}}
 private fun start()=Robolectric.buildActivity(BrowserActivity::class.java,Intent(Intent.ACTION_VIEW,Uri.parse("https://fixture.test/"))).setup().visible().also{settle(it.get())}
 private fun key(a:BrowserActivity,k:Int){a.dispatchKeyEvent(KeyEvent(0,k));a.dispatchKeyEvent(KeyEvent(1,k));settle(a)}
 private fun click(a:BrowserActivity,s:String){if(BrowserTestActions.settingsClick(a,s))return;if(s in listOf("Settings","History")&&views(a).any{it.contentDescription=="Menu popup"})key(a,97);var v:View=views(a).firstOrNull{it.isShown&&it.hasOnClickListeners()&&it.contentDescription==s}?:label(a,s)?:desc(a,s);while(!v.hasOnClickListeners())v=v.parent as View;v.performClick();settle(a)}
 private fun web(a:BrowserActivity)=views(a).filterIsInstance<WebView>().single()
 private fun address(a:BrowserActivity)=views(a).filterIsInstance<EditText>().first{it.contentDescription?.startsWith("Address or")==true}
 private fun motion(value:Float):MotionEvent{val p=MotionEvent.PointerProperties().apply{id=0};val c=MotionEvent.PointerCoords().apply{setAxisValue(MotionEvent.AXIS_RZ,value)};return MotionEvent.obtain(0,0,MotionEvent.ACTION_MOVE,1,arrayOf(p),arrayOf(c),0,0,1f,1f,0,0,InputDevice.SOURCE_JOYSTICK,0)}
 private fun stick(a:BrowserActivity,value:Float){val e=motion(value);a.dispatchGenericMotionEvent(e);e.recycle();TestFrameClock.advance(Duration.ofMillis(48))}
 @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
 @Test fun legendIsBlackOpaqueAndUnclippedOnPagesAndSettings(){val c=start();val a=c.get();for(settings in listOf(false,true)){if(settings)click(a,"Settings");val host=views(a).filterIsInstance<HorizontalScrollView>().first{it.contentDescription?.contains(" controls:")==true};val surface=host.parent as View;assertEquals(24,surface.height);assertEquals(Color.BLACK,(surface.background as ColorDrawable).color);assertEquals(1f,surface.alpha,.001f);val row=host.getChildAt(0) as ViewGroup;for(i in 0 until row.childCount){val hint=row.getChildAt(i);assertEquals(1f,hint.alpha,.001f);for(t in all(hint).filterIsInstance<TextView>()){val r=Rect();if(t.getGlobalVisibleRect(r))assertEquals("Clipped ${t.text}",t.height,r.height());assertTrue("Glyph ${t.text}: height=${t.height}, font=${t.paint.fontMetricsInt.descent-t.paint.fontMetricsInt.ascent}, size=${t.textSize}, settings=$settings",t.height>=t.paint.fontMetricsInt.let{it.descent-it.ascent})}}};c.pause().stop().destroy()}
 @Test fun landscapeSettingsPlacePrimaryCategoriesSideBySideWithoutScrolling(){val c=start();val a=c.get();click(a,"Settings");val boxes=listOf("Browsing","Appearance & accessibility","Controls").map{title->val r=Rect();assertTrue(label(a,title)!!.getGlobalVisibleRect(r));r};assertEquals(boxes[0].top,boxes[1].top);assertEquals(boxes[1].top,boxes[2].top);assertTrue(boxes[0].right<boxes[1].left);assertTrue(boxes[1].right<boxes[2].left);for(scroll in views(a).filterIsInstance<ScrollView>())assertFalse("Landscape settings require scrolling",scroll.canScrollVertically(1));for(title in listOf("Privacy & protection","Backup & restore","About & help")){val r=Rect();assertTrue("$title is hidden",label(a,title)!!.getGlobalVisibleRect(r))};c.pause().stop().destroy()}
 @Test fun contextActionsUseTheSameLeftDrawerOverTheUnchangedPage(){val c=start();val a=c.get();val original=web(a);a.dispatchKeyEvent(KeyEvent(0,96));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));a.dispatchKeyEvent(KeyEvent(1,96));val shadow=Shadows.shadowOf(original);assertTrue(shadow.lastEvaluatedJavascript.contains(".target()"));shadow.lastEvaluatedJavascriptCallback.onReceiveValue(JSONObject.quote("""{"link":"https://destination.test","title":"Fixture target","rect":{"left":20,"top":40,"width":90,"height":30},"viewportWidth":960}"""));TestFrameClock.advance(Duration.ofMillis(360));settle(a);val panel=desc(a,"Menu panel");val r=Rect();val page=Rect();assertTrue(panel.getGlobalVisibleRect(r));assertTrue((original.parent as View).getGlobalVisibleRect(page));assertEquals(page.left,r.left);assertTrue(r.top<=address(a).top);assertSame(original,web(a));assertNotNull(label(a,"Open in new tab"));c.pause().stop().destroy()}
 @Test fun historyPrecedesDownloadsAndShareInSurfBar(){val c=start();val a=c.get();val history=desc(a,"History");val downloads=desc(a,"Downloads");val share=desc(a,"Share page");assertSame(history.parent,downloads.parent);assertTrue(history.left<downloads.left);assertTrue(downloads.left<share.left);click(a,"History");assertNotNull(label(a,"Clear history"));c.pause().stop().destroy()}
 @Test fun findInPageUsesNativeFindApiAndKeepsTheWebViewAttached(){val c=start();val a=c.get();val original=web(a);key(a,109);click(a,"Find in page");val field=desc(a,"Find in page") as EditText;assertSame(original,web(a));field.setText("needle");TestFrameClock.advance(Duration.ofMillis(360));assertEquals("needle",RecordingWebViewShadow.findQueries.last());assertNotNull(RecordingWebViewShadow.findListener);RecordingWebViewShadow.findListener!!.onFindResultReceived(1,4,true);assertEquals("2/4",(desc(a,"Match count") as TextView).text.toString());click(a,"Next match");click(a,"Previous match");assertEquals(listOf(true,false),RecordingWebViewShadow.findDirections);click(a,"Close find");assertFalse(field.isShown);assertTrue(RecordingWebViewShadow.clearFindCalls>0);assertSame(original,web(a));c.pause().stop().destroy()}
 @Test fun oledAndRedAccentCanBeChosenIndependentlyWithoutDestroyingPages(){val c=start();val a=c.get();val original=web(a);click(a,"Settings");click(a,"Appearance");assertNotNull(label(a,"Accent colors"));click(a,"OLED theme");click(a,"Red accent");val p=a.getSharedPreferences("browser",0);assertEquals("OLED",p.getString("theme",null));assertEquals("Red",p.getString("accent",null));val theme=BrowserTheme.resolve(p.getString("theme","Dark")!!,true,p.getString("accent",null));assertEquals(Color.BLACK,theme.background);assertEquals(BrowserTheme.accentColor("Red",true),theme.accent);TestFrameClock.advance(Duration.ofMillis(360));for(name in BrowserTheme.names+BrowserTheme.accentNames){val v=desc(a,if(name in BrowserTheme.names)"$name theme"else"$name accent");val r=Rect();assertTrue(v.getGlobalVisibleRect(r));assertEquals(v.height,r.height())};key(a,97);key(a,97);key(a,97);assertSame(original,web(a));c.pause().stop().destroy()}
 @Test fun aNewTabFocusesAddressWithoutOpeningAnExtractEditor(){val c=start();val a=c.get();BrowserTestActions.openTabs(a);BrowserTestActions.newTab(a);val field=address(a);assertSame(field,a.window.decorView.findFocus());assertFalse(field.showSoftInputOnFocus);assertEquals(View.VISIBLE,desc(a,"Go").visibility);assertFalse(desc(a,"Go").isEnabled);key(a,96);assertTrue(desc(a,"Go").isShown);assertTrue(field.imeOptions and EditorInfo.IME_FLAG_NO_EXTRACT_UI!=0);assertTrue(field.imeOptions and EditorInfo.IME_FLAG_NO_FULLSCREEN!=0);key(a,97);key(a,97);c.pause().stop().destroy()}
 @Test fun selectTogglesMenuWhileAndroidBackNavigates(){val c=start();val a=c.get();val original=web(a);key(a,109);assertNotNull(label(a,"Menu"));assertSame(original,web(a));key(a,109);TestFrameClock.advance(Duration.ofMillis(360));settle(a);assertTrue(views(a).none{it.contentDescription=="Menu popup"});a.onBackPressed();settle(a);assertTrue(views(a).none{it.contentDescription=="Menu popup"});assertTrue((BrowserTestActions.call(a,"getTab") as BrowserActivity.Tab).home);c.pause().stop().destroy()}
 @Test fun dpadUpAtTheTopReachesBookmarksThenAddressAndTopActions(){val p=RuntimeEnvironment.getApplication().getSharedPreferences("browser",0);p.edit().putBoolean("favorites_bar",true).commit();BrowserData(p).record("https://bookmark.test/","Pinned bookmark","bookmarks");val c=start();val a=c.get();assertFalse(address(a).hasFocus());key(a,19);assertEquals("Bookmark: Pinned bookmark",a.window.decorView.findFocus()?.contentDescription);key(a,19);assertSame(address(a),a.window.decorView.findFocus());key(a,100);assertEquals("New tab",a.window.decorView.findFocus()?.contentDescription);c.pause().stop().destroy()}
 @Test fun nestedScrollUsesJavascriptOnlyAfterItsRouteProbe(){val c=start();val a=c.get();key(a,20);RecordingWebViewShadow.nativeScroll.clear();stick(a,1f);val shadow=Shadows.shadowOf(web(a));assertTrue(shadow.lastEvaluatedJavascript.contains(".canNativeScroll("));assertTrue(RecordingWebViewShadow.nativeScroll.isEmpty());shadow.lastEvaluatedJavascriptCallback.onReceiveValue("false");TestFrameClock.advance(Duration.ofMillis(48));assertTrue(RecordingWebViewShadow.scripts.any{it.contains(".setScroll(0.0,1800.0)")});assertTrue(RecordingWebViewShadow.nativeScroll.isEmpty());stick(a,0f);assertTrue(RecordingWebViewShadow.scripts.last{it.contains(".setScroll(")}.contains(".setScroll(0.0,0.0)"));c.pause().stop().destroy()}
 @Test fun aLateNestedRouteResultCannotRestartReleasedScrolling(){val c=start();val a=c.get();key(a,20);stick(a,1f);val shadow=Shadows.shadowOf(web(a));assertTrue(shadow.lastEvaluatedJavascript.contains(".canNativeScroll("));val callback=shadow.lastEvaluatedJavascriptCallback;stick(a,0f);RecordingWebViewShadow.clearEvidence();callback.onReceiveValue("false");TestFrameClock.advance(Duration.ofMillis(100));assertTrue(RecordingWebViewShadow.nativeScroll.isEmpty());assertTrue(RecordingWebViewShadow.scripts.none{it.contains(".setScroll(")&&!it.contains(".setScroll(0.0,0.0)")});c.pause().stop().destroy()}
}
